/*
Agent Name: architect
Step Number: 0
Reason for Mistake: The Architect assumed the problem could be solved by simply summing the maximum lengths of all snakes plus 1, implying the relative order of snakes does not matter. However, the constraint preventing collisions between adjacent snakes $i$ (left) and $j$ (right) is $x_j - x_i \ge \max_t(R_i(t) - D_j(t)) + 1$, which depends on the specific histories of enlargement ($R$) and shrinkage ($D$) for the specific pair of snakes. Since $R$ and $D$ vary per snake over time, the optimal gap depends on the permutation order. This fundamental oversight led to an $O(N+Q)$ solution that fails on test cases like Example 2 (predicts 10, expected 11), whereas the correct approach requires an $O(N^2 \cdot 2^N)$ bitmask dynamic programming solution to find the optimal permutation.
*/

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int INF = 1e9;

struct State {
    int x;      // Minimum starting position of the last snake
    int max_r;  // Minimum possible maximum reach of any snake in the set
};

// Global DP table to avoid stack overflow. Size: 2^20 * 20 * 8 bytes ~= 160 MB.
// Using 1-based indexing for snakes internally in logic, mapped to 0-based for mask.
// dp[mask][last_snake_index]
// Flattened for slightly better memory locality, or vector of vectors.
// vector<vector<State>> dp(1 << n, vector<State>(n));
// Due to memory constraints (potential 256MB limit), we use a single flat vector if needed, 
// but for N<=20, 160MB is usually acceptable. We will use vector.

int R[20];
int D[20];
int W[20][20];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    if (!(cin >> n >> q)) return 0;

    // Initialize W matrix. 
    // We process events on the fly to save O(N*Q) memory on storing full history.
    // Reset R and D arrays.
    for(int i=0; i<n; ++i) { R[i] = 0; D[i] = 0; }

    // W[i][j] stores max(R_i(t) - D_j(t)). Initialize with 0 (for t=0 state).
    for(int i=0; i<n; ++i) {
        for(int j=0; j<n; ++j) {
            W[i][j] = 0;
        }
    }

    for (int t = 0; t < q; ++t) {
        int s;
        char op;
        cin >> s >> op;
        --s; // 0-indexed
        if (op == '+') {
            R[s]++;
        } else {
            D[s]++;
        }

        // Update W for all pairs. 
        // Optimization: Only update W[i][j] where we care. All pairs.
        // Complexity: O(N^2 * Q) ~ 400 * 200000 = 8 * 10^7 ops. Acceptable.
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int diff = R[i] - D[j];
                if (diff > W[i][j]) {
                    W[i][j] = diff;
                }
            }
        }
    }

    // W[i][j] is now max(R_i - D_j). 
    // The required distance x_j - x_i is W[i][j] + 1.
    for(int i=0; i<n; ++i) {
        for(int j=0; j<n; ++j) {
            W[i][j] += 1;
        }
    }

    // DP State: dp[mask][i] = {min_start_pos_of_i, min_global_max_reach}
    // Use vector to handle heap allocation safely.
    // To optimize memory, we can pack State into int if values allow, but 160MB is okay.
    // We use vector<vector<State>>.
    int num_states = 1 << n;
    vector<vector<State>> dp(num_states, vector<State>(n, {INF, INF}));

    // Base cases: Single snake placed at 1. Reach = 1 + R[s](q)
    // Note: We need to know R[q] for each snake to calculate base reach.
    // But R array currently holds final R values after Q iterations!
    // Wait, R array holds R[s] after all updates. This IS R[s][q].
    // We saved R[s] in the array R[] during the loop.
    // So R[s] is the max enrichment count for snake s.

    for (int i = 0; i < n; ++i) {
        dp[1 << i][i] = {1, 1 + R[i]};
    }

    for (int mask = 1; mask < num_states; ++mask) {
        for (int i = 0; i < n; ++i) {
            if (dp[mask][i].x == INF) continue;

            // Try adding snake j
            for (int j = 0; j < n; ++j) {
                if (!(mask & (1 << j))) {
                    int next_mask = mask | (1 << j);

                    // New start position of j
                    int next_x = dp[mask][i].x + W[i][j];

                    // New max reach considering snake j
                    // Reach of j = next_x + R[j]
                    int new_reach = max(dp[mask][i].max_r, next_x + R[j]);

                    // Check if we improve the state for next_mask, j
                    // Priority: 1. Minimize max_reach. 2. Minimize x (helps future gaps?)
                    if (new_reach < dp[next_mask][j].max_r) {
                        dp[next_mask][j] = {next_x, new_reach};
                    } else if (new_reach == dp[next_mask][j].max_r) {
                        if (next_x < dp[next_mask][j].x) {
                            dp[next_mask][j].x = next_x;
                        }
                    }
                }
            }
        }
    }

    int ans = INF;
    int full_mask = num_states - 1;
    for (int i = 0; i < n; ++i) {
        if (dp[full_mask][i].max_r < ans) {
            ans = dp[full_mask][i].max_r;
        }
    }

    cout << ans << endl;

    return 0;
}
